insert into public.stats (id, source_code, value, unit, claim, verbatim, theme, scope, provenance, projection, isco, page, original_source) values
  ('wef-2025-skill-gaps-barrier', 'S06', 63, '%', 'Le déficit de compétences est le principal frein à la transformation des entreprises : 63 % des employeurs le citent comme obstacle majeur d’ici 2030.', 'Skill gaps are categorically considered the biggest barrier to business transformation … with 63% of employers identifying them as a major barrier over the 2025-2030 period.', 'competences', 'monde', 'primaire', false, '{}'::text[], 'p.6', null),
  ('wef-2025-skills-transformed-39', 'S06', 39, '%', 'En moyenne, 39 % des compétences actuelles des travailleurs seront transformées ou deviendront obsolètes entre 2025 et 2030.', 'workers can expect that two-fifths (39%) of their existing skill sets will be transformed or become outdated over the 2025-2030 period.', 'competences', 'monde', 'primaire', false, '{}'::text[], 'p.6', null),
  ('wef-2025-skill-instability-trend', 'S06', 44, '%', 'L’instabilité des compétences ralentit : 39 % en 2025, contre 44 % en 2023 et un pic de 57 % en 2020.', 'this measure of "skill instability" has slowed compared to previous editions of the report, from 44% in 2023 … and a high point of 57% in 2020.', 'competences', 'monde', 'primaire', false, '{}'::text[], 'p.6', null),
  ('wef-2025-ai-transforms-business-86', 'S06', 86, '%', '86 % des employeurs s’attendent à ce que l’IA et les technologies de traitement de l’information transforment leur activité d’ici 2030.', '86% of respondents expecting these technologies to transform their business by 2030', 'adoption', 'monde', 'primaire', false, '{}'::text[], 'p.10', null),
  ('wef-2025-jobs-churn-22', 'S06', 22, '%', 'D’ici 2030, la rotation structurelle du marché du travail (emplois créés + détruits) équivaudra à 22 % des emplois actuels.', 'job creation and destruction due to structural labour-market transformation will amount to 22% of today’s total jobs.', 'emploi', 'monde', 'primaire', true, '{}'::text[], 'p.5', null),
  ('wef-2025-jobs-created-170m', 'S06', 170, 'M', '170 millions de nouveaux emplois pourraient être créés d’ici 2030 (soit 14 % de l’emploi actuel).', 'the creation of new jobs equivalent to 14% of today’s total employment, amounting to 170 million jobs.', 'emploi', 'monde', 'primaire', true, '{}'::text[], 'p.5', null),
  ('wef-2025-jobs-displaced-92m', 'S06', 92, 'M', '92 millions d’emplois pourraient être détruits d’ici 2030 (soit 8 % de l’emploi actuel).', 'the displacement of the equivalent of 8% (or 92 million) of current jobs', 'emploi', 'monde', 'primaire', true, '{}'::text[], 'p.5', null),
  ('wef-2025-jobs-net-78m', 'S06', 78, 'M', 'Le solde net attendu est de +78 millions d’emplois d’ici 2030 (croissance nette de 7 % de l’emploi total).', 'resulting in net growth of 7% of total employment, or 78 million jobs.', 'emploi', 'monde', 'primaire', true, '{}'::text[], 'p.5', null),
  ('wef-2025-upskilling-priority-85', 'S06', 85, '%', '85 % des employeurs prévoient de prioriser la montée en compétences (upskilling) de leurs effectifs.', '85% of employers surveyed plan to prioritize upskilling their workforce', 'formation', 'monde', 'primaire', false, '{}'::text[], 'p.6', null),
  ('wef-2025-need-training-59', 'S06', 59, '%', '59 % des travailleurs auront besoin d’une formation d’ici 2030, et 11 % risquent de ne pas y avoir accès.', 'if the world’s workforce was made up of 100 people, 59 would need training by 2030 … 11 would be unlikely to receive the reskilling or upskilling needed', 'formation', 'monde', 'primaire', true, '{}'::text[], 'p.6', null),
  ('wef-2025-hire-new-skills-70', 'S06', 70, '%', '70 % des employeurs prévoient de recruter des profils dotés de nouvelles compétences.', '70% of employers expecting to hire staff with new skills', 'rh', 'monde', 'primaire', false, '{}'::text[], 'p.6', null),
  ('wef-2025-reduce-workforce-ai-40', 'S06', 40, '%', '40 % des employeurs prévoient de réduire leurs effectifs là où l’IA peut automatiser des tâches.', '40% anticipate reducing their workforce where AI can automate tasks.', 'rh', 'monde', 'primaire', false, '{}'::text[], 'p.6', null),
  ('wef-2025-tasks-humans-alone-47', 'S06', 47, '%', 'Aujourd’hui 47 % des tâches sont réalisées par des humains seuls, 22 % par la technologie et 30 % en combinaison des deux.', 'today, 47% of work tasks are performed mainly by humans alone, with 22% performed mainly by technology … and 30% completed by a combination of both.', 'productivite', 'monde', 'primaire', false, '{}'::text[], 'p.25', null),
  ('wef-2025-tasks-2030-humans-33', 'S06', 33, '%', 'D’ici 2030, la part des tâches réalisées par des humains seuls reculerait de 47 % à 33 %, la technologie passant à 34 % et la combinaison humain-machine à 33 % : la répartition deviendrait quasi équilibrée entre les trois.', 'By 2030, employers expect these proportions to be nearly evenly split across these three categories/approaches (Figure 2.7). [People 33% / Technology 34% / Combination 33%]', 'productivite', 'monde', 'primaire', true, '{}'::text[], 'p.26', null),
  ('wef-2025-ai-jobs-created-displaced', 'S06', 11, 'M', 'Les technologies d’IA créeraient 11 millions d’emplois tout en en détruisant 9 millions d’ici 2030.', 'trends in AI and information processing technology are expected to create 11 million jobs, while simultaneously displacing 9 million others', 'emploi', 'monde', 'primaire', true, '{}'::text[], 'p.25', null),
  ('parlonsrh-2025-metier-transforme-87', 'FR1', 87, '%', '87 % des professionnels RH jugent que leur métier va être transformé par l’IA.', '87 % des professionnels RH jugent que leur métier va être transformé par l’IA', 'emploi', 'france', 'primaire', false, '{}'::text[], 'p.4', null),
  ('parlonsrh-2025-usage-individuel-83', 'FR1', 83, '%', '83 % des professionnels RH utilisent déjà l’IA à titre individuel.', '83 % des professionnels RH utilisent l’IA à titre individuel', 'adoption', 'france', 'primaire', false, '{}'::text[], 'p.4', null),
  ('parlonsrh-2025-opportunite-82', 'FR1', 82, '%', '82 % des professionnels RH perçoivent l’IA comme une opportunité pour la fonction RH.', '82 % des professionnels RH perçoivent l’IA comme une opportunité pour la fonction RH', 'adoption', 'france', 'primaire', false, '{}'::text[], 'p.4', null),
  ('parlonsrh-2025-risque-confidentialite-80', 'FR1', 80, '%', '80 % des professionnels RH redoutent les conséquences de l’IA sur la confidentialité et la vie privée (84 % chez les RH en entreprise).', 'la confidentialité et la sécurité des données (80 % des répondants, et même 84 % chez les professionnels RH en entreprise).', 'gouvernance', 'france', 'primaire', false, '{}'::text[], 'p.30', null),
  ('parlonsrh-2025-service-rh-deploye-37', 'FR1', 37, '%', 'Seuls 37 % des professionnels RH évoluent dans un service où au moins un outil intégrant l’IA a été déployé. L’usage individuel (83 %) devance largement l’intégration collective.', '37 % d’entre eux évoluent dans un service RH où l’un de ces outils a été déployé', 'adoption', 'france', 'primaire', false, '{}'::text[], 'p.11', null),
  ('parlonsrh-2025-formation-ia-47', 'FR1', 47, '%', '47 % des entreprises ont déployé des formations à l’IA dans le service RH au cours des 3 dernières années.', '47 % des entreprises interrogées ont déployé des formations à l’IA au sein du service RH au cours des 3 dernières années', 'formation', 'france', 'primaire', false, '{}'::text[], 'p.11', null),
  ('parlonsrh-2025-frein-strategie-52', 'FR1', 52, '%', 'L’absence de stratégie claire est le premier frein au déploiement de l’IA dans les RH, cité par 52 % des professionnels.', 'L’absence de stratégie claire (52 %)', 'gouvernance', 'france', 'primaire', false, '{}'::text[], 'p.29', null),
  ('parlonsrh-2025-frein-competences-49', 'FR1', 49, '%', 'Le manque de compétences en interne est le 2ᵉ frein au déploiement de l’IA dans les RH, cité par 49 % des professionnels.', 'le manque de compétences internes (49 %)', 'competences', 'france', 'primaire', false, '{}'::text[], 'p.29', null),
  ('parlonsrh-2025-transition-difficile-61', 'FR1', 61, '%', '61 % des professionnels RH anticipent une transition difficile vers des RH assistés par l’IA.', 'Les professionnels RH anticipent majoritairement une transition difficile vers les RH assistés par l’IA (61 %).', 'adoption', 'france', 'primaire', false, '{}'::text[], 'p.34', null),
  ('parlonsrh-2025-confiance-avenir-69', 'FR1', 69, '%', 'Près de 7 professionnels RH sur 10 (69 %) se déclarent confiants dans l’avenir de leur organisation à l’ère de l’IA.', '7 répondants sur 10 affichent leur confiance dans l’avenir de leur organisation à l’ère de l’IA.', 'adoption', 'france', 'primaire', false, '{}'::text[], 'p.34', null),
  ('parlonsrh-2025-marketing-transforme-96', 'FR1', 96, '%', 'Pour les professionnels RH, le marketing et la communication (96 %), l’informatique (93 %) et la relation client (79 %) sont les métiers les plus transformés par l’IA.', 'l’impact de l’IA sur les métiers du marketing et de la communication (96 %) … de l’informatique (93 %) … la relation client (79 %)', 'emploi', 'france', 'primaire', false, array['24', '25', '42']::text[], 'p.38', null),
  ('centreinffo-2025-actifs-ia-travail-53', 'FR1', 53, '%', '53 % des actifs français ont déjà utilisé l’IA au travail (71 % chez les cadres et professions intellectuelles supérieures).', '53 % des actifs ont ainsi déjà utilisé l’IA au travail. … On monte à 71 % … « cadres et professions intellectuelles supérieures ».', 'adoption', 'france', 'secondaire', false, '{}'::text[], 'p.12', 'Baromètre Centre Inffo 2025'),
  ('credoc-2025-francais-ia-pro-22', 'FR1', 22, '%', 'Seuls 22 % des Français ont déjà utilisé des outils d’IA dans un cadre professionnel.', 'seuls 22 % des Français ont déjà utilisé des outils d’intelligence artificielle dans le cadre professionnel.', 'adoption', 'france', 'secondaire', false, '{}'::text[], 'p.11', 'Crédoc — Baromètre du Numérique 2025'),
  ('idc-2025-services-rh-sans-ia-53', 'FR1', 53, '%', '53 % des services RH (Europe et Amériques) n’utilisent pas l’IA, et seuls 10 % ont déployé des fonctionnalités IA dans leur SIRH.', '53 % des services RH n’utilisent pas l’IA … Seuls 10 % ont déployé des fonctionnalités IA dans leur SIRH', 'adoption', 'monde', 'secondaire', false, '{}'::text[], 'p.27', 'IDC pour Cegid (840 responsables RH)'),
  ('ocde-2025-capability-levels-2-3', 'S08', 3, '', 'Les systèmes d’IA les plus avancés se situent entre les niveaux 2 et 3 (sur 5) des échelles de capacités de l’OCDE : ils restent loin d’une équivalence humaine.', 'les capacités des systèmes d’IA actuels … se situent entre les niveaux 2 et 3 des différentes échelles.', 'exposition', 'ocde', 'primaire', false, '{}'::text[], 'p.9', null),
  ('ocde-2025-langage-niveau-3', 'S08', 3, '', 'Les grands modèles de langage (type GPT-4o) atteignent le seuil inférieur du niveau 3 sur l’échelle du langage, mais ne sont qu’au niveau 2 pour l’interaction sociale.', 'les grands modèles de langage les plus avancés … sont classés au seuil inférieur du niveau 3 … classés au niveau 2 sur l’échelle de l’interaction sociale', 'exposition', 'ocde', 'primaire', false, '{}'::text[], 'p.14', null),
  ('ocde-2024-adoption-moyenne-8', 'S05', 8, '%', 'En 2023, seules 8 % des entreprises utilisaient l’IA en moyenne dans les pays de l’OCDE, et l’adoption reste très inégale.', 'compared to an overall adoption rate of 8% in the same year on average across OECD countries', 'adoption', 'ocde', 'primaire', false, '{}'::text[], 'p.3', null),
  ('ocde-2024-grandes-entreprises-2x', 'S05', 2, 'x', 'Les entreprises de plus de 250 salariés affichent souvent une part d’utilisateurs de l’IA presque deux fois supérieure à celle des plus petites entreprises.', 'firms with more than 250 employees … often have nearly double the share of AI users compared to smaller firms.', 'adoption', 'ocde', 'primaire', false, '{}'::text[], 'p.3', null),
  ('ilo-2023-clerical-exposure-82', 'S01', 82, '%', 'Le travail administratif est le plus exposé à l’IA générative : 82 % de ses tâches le sont à un niveau supérieur à la moyenne (dont 24 % fortement).', 'a full 82 per cent of clerical job tasks are exposed at an above-average level.', 'exposition', 'monde', 'primaire', false, array['41', '42', '43', '44']::text[], 'p.24', null),
  ('ilo-2023-augmentation-dominante-13', 'S01', 13.4, '%', 'L’effet dominant de l’IA générative est l’augmentation (assistance), pas le remplacement : elle pourrait toucher 13,4 % de l’emploi dans les pays à haut revenu.', 'The greater impact is from augmentation, which has the potential to affect … 13.4 percent of employment in high-income countries.', 'emploi', 'ocde', 'primaire', false, '{}'::text[], 'p.1', null),
  ('ilo-2023-femmes-plus-exposees', 'S01', 7.8, '%', 'Dans les pays à haut revenu, 7,8 % de l’emploi féminin est potentiellement automatisable par l’IA générative, contre 2,9 % de l’emploi masculin.', 'the share of potentially affected female jobs is 7.8 per cent, more than double the 2.9 per cent of male jobs for that income group.', 'emploi', 'ocde', 'primaire', false, '{}'::text[], 'p.35', null),
  ('indeed-2025-jobs-highly-transformed-26', 'S10', 26, '%', '26 % des offres d’emploi pourraient être « fortement » transformées par l’IA générative, et 54 % « modérément ».', 'More than a quarter (26%) of jobs … could be "highly" transformed by GenAI. But the majority (54%) are likely to be "moderately" transformed', 'exposition', 'usa', 'primaire', false, '{}'::text[], 'p.3', null),
  ('indeed-2025-skills-exposed-41', 'S10', 41, '%', '41 % des ~2 900 compétences professionnelles analysées sont exposées au plus haut niveau de transformation potentielle par l’IA générative.', '41% of almost 2,900 common work skills assessed are exposed to the highest potential levels of GenAI-driven transformation', 'competences', 'usa', 'primaire', false, '{}'::text[], 'p.4', null),
  ('indeed-2025-skills-fully-replaceable-1', 'S10', 1, '%', 'Aujourd’hui, seulement 1 % des compétences relèvent de la catégorie « totalement remplaçable » par l’IA générative : l’assistance domine, pas le remplacement.', 'only 1% of skills fall into the "fully transformable" category today', 'competences', 'usa', 'primaire', false, '{}'::text[], 'p.11', null),
  ('neobrain-2024-tertiaire-france-expose-33', 'FR4', 33, '%', 'En France, près d’un tiers de l’activité professionnelle du secteur tertiaire est exposé à l’IA générative.', 'un tiers de l’activité professionnelle est exposé à cette technologie', 'exposition', 'france', 'secondaire', false, '{}'::text[], 'p.8', 'Sopra Steria Next'),
  ('neobrain-2024-entreprises-fr-genai-60', 'FR4', 60, '%', 'En France, 60 % des entreprises utilisent ou adoptent l’IA générative.', 'En France, 60 % des entreprises utilisent ou adoptent l’IA générative', 'adoption', 'france', 'secondaire', false, '{}'::text[], 'p.8', null),
  ('neobrain-2024-heures-europe-automatisables-27', 'FR4', 27, '%', 'D’ici 2030, 27 % des heures travaillées en Europe pourraient être automatisées.', 'D’ici 2030, 27 % des heures travaillées en Europe pourraient être automatisées', 'emploi', 'europe', 'secondaire', true, '{}'::text[], 'p.8', 'McKinsey Global Institute'),
  ('neobrain-2024-competences-evoluent-25', 'FR4', 25, '%', 'Les compétences des métiers exposés à l’IA évoluent 25 % plus vite, exigeant une adaptation constante.', 'Les compétences des métiers exposés à l’IA évoluent 25 % plus vite, exigeant une adaptation constante', 'competences', 'france', 'secondaire', false, '{}'::text[], 'p.8', null),
  ('cianum-2025-cout-inference-90x', 'S07', 90, 'x', 'Le coût moyen de l’inférence IA (par jeton) a été divisé par 90 en 18 mois : la barrière économique à l’adoption s’effondre.', 'le coût moyen de l’inférence, mesuré par jeton (token), a été divisé par 90 en 18 mois', 'adoption', 'monde', 'secondaire', false, '{}'::text[], 'p.6', 'Epoch AI'),
  ('cianum-2025-ai-act-sanctions', 'S07', 7, '%', 'En cas de non-conformité à l’AI Act, les sanctions peuvent atteindre 30 millions d’euros ou 7 % du chiffre d’affaires annuel mondial.', 'les sanctions peuvent aller jusqu’à 30 millions d’euros ou 7 % du chiffre d’affaires annuel.', 'gouvernance', 'europe', 'primaire', false, '{}'::text[], 'p.8', null),
  ('stanford-2026-genai-adoption-53', 'S02', 53, '%', 'L’IA générative a atteint ~53 % d’adoption en trois ans, plus vite que l’ordinateur personnel ou internet.', 'Generative AI reached 53% adoption in three years, faster than the personal computer or the internet.', 'adoption', 'monde', 'primaire', false, '{}'::text[], 'ch.4', null),
  ('stanford-2026-orgs-adoption-88', 'S02', 88, '%', 'En 2025, 88 % des organisations interrogées déclarent utiliser l’IA, et 70 % dans au moins une fonction métier.', 'up to 88% of surveyed organizations … Generative AI is now used in at least one business function at 70% of organizations', 'adoption', 'monde', 'primaire', false, '{}'::text[], 'ch.4', null),
  ('stanford-2026-productivite-europe-4', 'S02', 4, '%', 'Une étude de 12 000 entreprises européennes montre que l’adoption de l’IA a augmenté la productivité du travail de 4 %, la formation renforçant l’effet.', 'A study of 12,000 European firms found that AI adoption boosted labor productivity by 4%, with training strengthening the outcome', 'productivite', 'europe', 'secondaire', false, '{}'::text[], 'p.220', 'Aldasoro et al., 2026'),
  ('stanford-2026-responsible-ai-policy', 'S02', 11, '%', 'Les rôles de gouvernance dédiés à l’IA ont crû de 17 % en 2025, et la part d’entreprises sans politique d’IA responsable est tombée de 24 % à 11 %.', 'AI-specific governance roles grew 17% in 2025, and the share of businesses with no responsible AI policies in place fell sharply from 24% to 11%.', 'gouvernance', 'monde', 'primaire', false, '{}'::text[], 'ch.3', null),
  ('pwc-2025-revenue-per-employee-3x', 'S12', 3, 'x', 'Les secteurs les plus exposés à l’IA affichent une croissance du revenu par employé 3 fois supérieure à celle des secteurs les moins exposés.', 'Industries most able to use AI have 3x higher growth in revenue generated by each employee', 'productivite', 'monde', 'primaire', false, '{}'::text[], 'p.2', null),
  ('pwc-2025-wage-premium-56', 'S12', 56, '%', 'Les travailleurs dotés de compétences IA (ex. prompt engineering) bénéficient d’une prime salariale moyenne de 56 % (contre 25 % un an plus tôt).', 'Workers with AI skills like prompt engineering command a 56% wage premium (up from 25% last year)', 'competences', 'monde', 'primaire', false, '{}'::text[], 'p.2', null),
  ('pwc-2025-skills-changing-faster-66', 'S12', 66, '%', 'Les compétences recherchées évoluent 66 % plus vite dans les métiers les plus exposés à l’IA (contre 25 % un an plus tôt).', 'Skills sought by employers are changing 66% faster in occupations most exposed to AI … up from 25% last year', 'competences', 'monde', 'primaire', false, '{}'::text[], 'p.2', null),
  ('pwc-2025-headcount-82', 'S12', 82, '%', '82 % des dirigeants déclarent que l’IA a augmenté leurs effectifs ou n’a entraîné aucun changement. L’IA reconfigure les emplois plus qu’elle ne les supprime massivement.', '82% say that AI has increased or caused no change in headcount', 'rh', 'monde', 'primaire', false, '{}'::text[], 'p.25', null),
  ('pwc-2025-job-growth-exposed-38', 'S12', 38, '%', 'L’emploi continue de croître dans presque tous les métiers exposés à l’IA, mais plus lentement (+38 % sur 5 ans) que dans les métiers peu exposés (+65 %).', 'job numbers are growing more slowly in occupations more exposed to AI (38% growth in the past five years) versus occupations less exposed to AI (65% growth …)', 'emploi', 'monde', 'primaire', false, '{}'::text[], 'p.11', null),
  ('mit-2025-iceberg-hidden-5x', 'S13', 5, 'x', 'L’exposition réelle des métiers à l’IA est cinq fois plus grande que l’adoption visible : elle touche surtout l’administratif, la finance et les services professionnels.', 'The hidden mass beyond visible tech sectors is five times larger.', 'exposition', 'usa', 'primaire', false, array['24', '41', '43']::text[], 'p.9', null),
  ('mit-2025-tasks-ai-can-do-16', 'S13', 16, '%', 'Les systèmes d’IA actuels peuvent techniquement réaliser environ 16 % des tâches de travail recensées.', 'current AI systems can technically perform approximately 16 percent of classified labor tasks', 'exposition', 'usa', 'primaire', false, '{}'::text[], 'p.2', null),
  ('parlonsrh-2026-remplacement-effectifs-64-16', 'FR2', 64, '%', '64 % des professionnels RH pensent que les entreprises vont remplacer des effectifs RH par l’IA, mais seuls 16 % l’anticipent dans leur propre entreprise.', '64 % des professionnels RH pensent que les entreprises vont remplacer des effectifs RH par l’IA… mais seuls 16 % estiment que cela aura lieu dans leur propre entreprise', 'emploi', 'france', 'primaire', false, '{}'::text[], 'p.4', null),
  ('parlonsrh-2026-agent-conversationnel-80', 'FR2', 80, '%', '80 % des professionnels RH utilisent un agent conversationnel dans leur pratique quotidienne (+13 points en un an).', '80 % des professionnels RH utilisent un agent conversationnel dans leur pratique quotidienne — +13 points', 'adoption', 'france', 'primaire', false, '{}'::text[], 'p.15', null),
  ('parlonsrh-2026-formations-ia-drh-65', 'FR2', 65, '%', '65 % des entreprises ont déployé des formations à l’IA dans le département RH (+18 points en un an).', '65 % des entreprises ont déployé des formations à l’IA dans le département RH — +18 points', 'formation', 'france', 'primaire', false, '{}'::text[], 'p.15', null),
  ('parlonsrh-2026-connaissance-ia-47', 'FR2', 47, '%', 'L’acculturation progresse : 47 % des professionnels RH déclarent connaître « assez bien » l’IA en 2026, contre 39 % en 2025.', 'Comment évaluez-vous votre connaissance de l’IA ? Je connais assez bien : 47 % (2026) / 39 % (2025)', 'competences', 'france', 'primaire', false, '{}'::text[], 'p.16', null),
  ('parlonsrh-2026-politique-encadrant-ia-34', 'FR2', 34, '%', 'Seules 34 % des organisations disposent d’une politique encadrant l’IA : 63 % au-delà de 5 000 salariés, mais 10 % en deçà de 10 salariés.', 'Votre organisation dispose-t-elle d’une politique encadrant l’IA ? Oui 34 % … Plus de 5000 salariés : 63 % … Moins de 10 salariés : 10 %', 'gouvernance', 'france', 'primaire', false, '{}'::text[], 'p.34', null),
  ('parlonsrh-2026-opportunite-81', 'FR2', 81, '%', '81 % des professionnels RH voient l’IA comme une opportunité pour la fonction RH en 2026 (stable vs 82 % en 2025).', 'Pour la fonction RH, l’IA est-elle plutôt UNE OPPORTUNITÉ : 81 % (2026) / 82 % (2025)', 'rh', 'france', 'primaire', false, '{}'::text[], 'p.41', null),
  ('parlonsrh-2026-taches-supprimees-25', 'FR2', 25, '%', 'Seules 25 % des entreprises déclarent avoir déjà supprimé des tâches ou étapes RH grâce à l’IA : l’effet sur l’organisation reste émergent.', 'Avez-vous supprimé des tâches/étapes RH grâce à l’IA ? Oui 25 % / Non 55 % / Je ne sais pas 20 %', 'emploi', 'france', 'primaire', false, '{}'::text[], 'p.23', null),
  ('parlonsrh-2026-emploi-jeunes-51', 'FR2', 51, '%', 'Dans 51 % des entreprises, l’IA a un impact positif sur l’emploi des jeunes.', 'Dans 51 % des entreprises, l’IA a un impact positif sur l’emploi des jeunes', 'emploi', 'france', 'primaire', false, '{}'::text[], 'p.6', null),
  ('cegos-2025-ia-enjeu-competences-63', 'FR3', 63, '%', 'Pour 63 % des RH, l’IA est le premier enjeu de compétences des deux prochaines années, devant l’évolution des systèmes d’information (38 %) et la cybersécurité (35 %).', 'les enjeux compétences des 2 ans à venir … boom de l’intelligence artificielle … Intelligence artificielle (IA) 63 %', 'competences', 'france', 'primaire', false, '{}'::text[], 'p.1', null),
  ('cegos-2025-obsolescence-emplois-19', 'FR3', 19, '%', 'Pour les RH, en moyenne 1 emploi sur 5 (19 %) court un risque d’obsolescence des compétences à horizon 3 ans.', 'Pour les RH, 1 emploi sur 5 court un risque d’obsolescence des compétences, à horizon 3 ans … En moyenne 19 %', 'competences', 'france', 'primaire', false, '{}'::text[], 'p.1', null),
  ('cegos-2025-competences-digitales-43', 'FR3', 43, '%', 'Pour 43 % des RH, ce sont les compétences digitales des collaborateurs qui doivent impérativement être renforcées, devant les compétences transversales (38 %).', 'Pour 43 % des RH, ce sont les compétences digitales des collaborateurs qui doivent impérativement être renforcées', 'competences', 'france', 'primaire', false, '{}'::text[], 'p.2', null),
  ('cegos-2025-developpement-levier-strategique-90', 'FR3', 90, '%', 'Le développement des compétences est jugé stratégique par 90 % des DRH (et 78 % des salariés).', 'Le développement des compétences est très largement considéré comme un levier stratégique … RH Total Oui 90% … Salariés Total Oui 78%', 'formation', 'france', 'primaire', false, '{}'::text[], 'p.3', null),
  ('cegos-2025-reconversions-90', 'FR3', 90, '%', '9 RH sur 10 (90 %) déclarent désormais accompagner les reconversions professionnelles, en particulier les mobilités internes.', 'Reconversions professionnelles : 9 RH sur 10 déclarent désormais les accompagner … Oui 90 %', 'formation', 'france', 'primaire', false, '{}'::text[], 'p.10', null),
  ('s04-2025-productivite-equipe-60', 'S04', 60, '%', 'Dans une étude expérimentale, les équipes humain-IA ont produit 60 % de productivité en plus par travailleur, avec une qualité supérieure.', 'creating 60% greater productivity per worker and higher-quality ad copy', 'productivite', 'usa', 'primaire', false, '{}'::text[], 'Abstract', null),
  ('s04-2025-groupes-humain-ia-85', 'S04', 85, '%', 'Une revue de plus de 5 000 études montre que les groupes humain-IA surpassent les humains seuls dans 85 % des cas.', 'Vaccaro et al. (2024) shows that human-AI groups outperform humans alone in 85% of the studies.', 'productivite', 'monde', 'secondaire', false, '{}'::text[], 'Introduction', 'Vaccaro et al., 2024'),
  ('s04-2025-ecriture-llm-40', 'S04', 40, '%', 'Les grands modèles de langage réduisent de 40 % le temps des tâches d’écriture professionnelle intermédiaire et en augmentent la qualité de 18 %.', 'large language models (LLMs) decreased the average time taken for mid-level professional writing tasks by 40% and increased quality by 18% (Noy and Zhang, 2023)', 'productivite', 'usa', 'secondaire', false, '{}'::text[], 'Introduction', 'Noy & Zhang, 2023'),
  ('s14-2024-exposition-emploi-positif', 'S14', 11.3, 'pts', 'Entre 2012 et 2022, une plus forte exposition à l’IA est allée de pair avec une croissance de l’emploi plus élevée (+11,3 points) : exposition ne signifie pas destruction.', 'a one standard deviation increase in AI exposure was associated with 11.3 percentage points higher employment growth', 'emploi', 'ocde', 'primaire', false, '{}'::text[], 'p.28', null),
  ('s14-2024-risque-auto-diplome-22', 'S14', 22, '%', 'Le risque d’automatisation est très inégal selon le diplôme : 22 % des travailleurs peu diplômés occupent un métier à haut risque, contre 2 % des diplômés du supérieur.', '2% of university-educated workers are in occupations at high risk of automation … and 22% of those with lower levels.', 'exposition', 'ocde', 'primaire', false, '{}'::text[], 'p.24', null),
  ('s14-2024-risque-auto-genre-12-6', 'S14', 12, '%', '12 % des hommes occupent un métier à haut risque d’automatisation, contre 6 % des femmes.', '12% of male workers are in occupations at high risk of automation vs. 6% of female workers.', 'exposition', 'ocde', 'primaire', false, '{}'::text[], 'p.24', null),
  ('s14-2024-exposition-diplomes-70', 'S14', 70, '%', 'Les diplômés du supérieur représentent 70 % des effectifs des métiers les plus exposés à l’IA, contre 9 % des moins exposés.', 'Tertiary-educated workers make up on average 70% of the workforce of the fifth quintile … compared to just 9% in the first quintile', 'exposition', 'ocde', 'primaire', false, '{}'::text[], 'p.20', null),
  ('s14-2024-formation-peu-qualifies-23', 'S14', 23, 'pts', 'Les adultes peu qualifiés ont 23 points de probabilité de moins de se former que les autres : l’accès à la formation est un enjeu d’équité face à l’IA.', 'Adults with low skills … are 23 percentage points less likely to train than those with medium/higher skills (OECD, 2019)', 'formation', 'ocde', 'secondaire', false, '{}'::text[], 'p.39', 'OCDE, 2019'),
  ('dares-2030-agents-entretien-490k', 'FR5', 490000, '', 'Métier de terrain en forte tension de recrutement : 490 000 postes seraient à pourvoir chez les agents d’entretien entre 2019 et 2030, dont 460 000 dus aux départs en fin de carrière. L’enjeu est le renouvellement, pas la suppression.', 'entre 2019 et 2030, 490 000 postes seraient à pourvoir chez les agents d’entretien, dont 460 000 dus aux départs en fin de carrière', 'emploi', 'france', 'primaire', true, array['91']::text[], 'Figure A', null),
  ('dares-2030-aide-domicile-creations-100k', 'FR5', 100000, '', 'L’aide à domicile est l’un des métiers en plus forte création nette d’emplois d’ici 2030 (+100 000 postes) : la demande de soin et d’accompagnement croît, l’IA y joue un rôle d’appui plus que de substitution.', 'Viendraient ensuite les aides à domicile (+100 000) et les ouvriers qualifiés de la manutention (+80 000)', 'emploi', 'france', 'primaire', true, array['53']::text[], 'Figure A', null),
  ('dares-2030-manutention-creations-80k', 'FR5', 80000, '', 'Les ouvriers qualifiés de la manutention figurent parmi les métiers en forte création nette d’emplois d’ici 2030 (+80 000 postes).', 'Viendraient ensuite les aides à domicile (+100 000) et les ouvriers qualifiés de la manutention (+80 000)', 'emploi', 'france', 'primaire', true, array['93']::text[], 'Figure A', null),
  ('dares-2030-batiment-second-oeuvre-deficit', 'FR5', 177000, '', 'Métier du bâtiment en tension : 177 000 besoins de recrutement chez les ouvriers qualifiés du second œuvre d’ici 2030 (150 000 départs + 27 000 créations) pour seulement 107 000 jeunes débutants attendus.', 'chez les ouvriers qualifiés du second œuvre du bâtiment, le déséquilibre potentiel entre les 177 000 besoins de recrutement … et le nombre de jeunes débutants (107 000)', 'emploi', 'france', 'primaire', true, array['71', '74']::text[], 'Figure A', null),
  ('dares-2030-commerce-creations-200-300k', 'FR5', 250000, '', 'Le commerce fait partie des domaines créant le plus d’emplois nets d’ici 2030 (entre 200 000 et 300 000 créations), soutenant les métiers de la vente.', 'le commerce –, avec chacun entre 200 000 et 300 000 créations nettes d’emplois', 'emploi', 'france', 'primaire', true, array['52']::text[], 'p.4', null),
  ('dares-2030-conducteurs-departs-34', 'FR5', 34, '%', 'Les conducteurs de véhicules sont un métier en légère croissance mais sous forte tension de renouvellement : les départs en fin de carrière y sont parmi les plus élevés (34 %) et les jeunes débutants ne suffiraient pas à les remplacer. L’enjeu est l’attractivité, pas la suppression par l’IA.', 'Les conducteurs de véhicules sont un métier légèrement en croissance, dont le nombre de départs en fin de carrière est parmi les plus élevés (34 %). Les jeunes débutant en emploi ne suffiraient pas à remplacer tous ces départs.', 'emploi', 'france', 'primaire', true, array['83']::text[], 'p.125', null),
  ('dares-2030-maintenance-postes-33', 'FR5', 33, '%', 'Les techniciens et agents de maîtrise de la maintenance sont en tension de recrutement : les postes à pourvoir d’ici 2030 représenteraient 33 % de l’emploi du métier de 2019. L’enjeu est le renouvellement des compétences, pas la suppression par l’IA.', 'les besoins de recrutement sont importants mais ils représentent une plus faible proportion de l’emploi du métier : c’est le cas en particulier des vendeurs (19 %), des enseignants (31 %), des techniciens et agents de maîtrise de la maintenance (33 %)', 'emploi', 'france', 'primaire', true, array['72']::text[], 'p.98', null),
  ('mckinsey-2017-physique-previsible-90', 'S15', 90, '%', 'Les métiers à forte composante d’activités physiques répétitives en environnement prévisible (production, conduite de machines, manutention) ont un potentiel d’automatisation technique élevé (supérieur à 90 % pour certains, comme les soudeurs en usine), quand les métiers d’interaction (relation client) restent sous 30 %. C’est un potentiel technique à horizon long (robotique), pas une suppression immédiate.', 'occupations that have a large proportion of physical activities in predictable environments such as factory welders have a technical automation potential above 90 percent, whereas for customer service representatives that potential is less than 30 percent', 'exposition', 'monde', 'primaire', false, array['81', '82', '93']::text[], 'p.26', null),
  ('mckinsey-2017-occupations-30pct-60', 'S15', 60, '%', 'Peu de métiers sont entièrement automatisables, mais 60 % des métiers ont au moins 30 % de leurs activités techniquement automatisables : l’automatisation transforme surtout des tâches, elle ne supprime pas des métiers entiers.', 'While few occupations are fully automatable, 60 percent of all occupations have at least 30 percent technically automatable activities', 'emploi', 'monde', 'primaire', false, '{}'::text[], 'Synthèse', null),
  ('mckinsey-2017-activites-moitie-50', 'S15', 50, '%', 'Environ la moitié des activités de travail dans le monde ont le potentiel technique d’être automatisées avec les technologies déjà démontrées, mais la part réellement automatisée d’ici 2030 sera bien plus faible.', 'about half of all work activities globally have the technical potential to be automated by adapting currently demonstrated technologies', 'exposition', 'monde', 'primaire', false, '{}'::text[], 'Synthèse', null),
  ('iag-2026-usage-ia-europe-28', 'S16', 28, '%', 'En Europe, environ 28 % des salariés adultes utilisent déjà l’IA sur leur lieu de travail, et l’usage est plus répandu en France, en Belgique, en Allemagne et au Luxembourg que dans le sud de l’Europe.', 'about 28% of European adult workers are already using AI at their workplace (Cedefop, 2025) … AI use is more common in some western European countries (Belgium, Germany, France, Luxembourg) than in southern European countries', 'adoption', 'europe', 'secondaire', false, '{}'::text[], 'p.10', 'Cedefop, 2025 (enquête 2024, 11 pays de l’UE)'),
  ('iag-2026-management-algorithmique-79', 'S16', 79, '%', 'En France, en Allemagne, en Italie et en Espagne, 79 % des employeurs en moyenne ont adopté au moins un outil qui donne des consignes aux salariés, suit ou évalue leur travail par algorithme (90 % aux États-Unis).', 'AM in workplaces is particularly prevalent in the US, where 90% of employers have adopted at least one tool to instruct, monitor or evaluate workers. Adoption is slightly lower in the European countries surveyed (France, Germany, Italy and Spain, with an average adoption of 79%)', 'gouvernance', 'europe', 'secondaire', false, '{}'::text[], 'p.11', 'OCDE, 2025 (enquête auprès de plus de 6 000 managers)'),
  ('iag-2026-algorithmes-flux-travail-24', 'S16', 24, '%', 'Pour 24 % des travailleurs de l’Union européenne, ce sont des algorithmes qui déterminent le déroulé du travail ou l’ordre de priorité des tâches.', 'The AIM-WORK survey found that algorithms determine the workflow or task prioritisation at work for 24% of EU workers (JRC, 2025a).', 'rh', 'europe', 'secondaire', false, '{}'::text[], 'p.11', 'JRC, enquête AIM-WORK 2024-2025'),
  ('iag-2026-taches-reorganisees-67', 'S16', 67, '%', 'En Europe, après l’adoption de l’IA, environ un tiers des salariés ne réalisent plus certaines tâches, 4 sur 10 en réalisent de nouvelles et 67 % effectuent certaines tâches plus vite : l’IA recompose le contenu du travail.', 'about one-third of European workers who participated in the survey no longer do some tasks after the adoption of AI as part of their main job, while about 4 in 10 workers now do some new or different tasks. Moreover, 67% of workers do some tasks faster than before (Cedefop, 2025).', 'productivite', 'europe', 'secondaire', false, '{}'::text[], 'p.12', 'Cedefop, 2025'),
  ('iag-2026-employeurs-taches-automatisees-72', 'S16', 72, '%', 'Dans la finance et l’industrie manufacturière, 66 % et 72 % des employeurs indiquent que l’IA a automatisé des tâches autrefois réalisées par des salariés, et environ la moitié qu’elle a créé des tâches nouvelles.', '66% and 72% of employers in finance and manufacturing, respectively, report that AI had automated tasks previously done by workers, while around half of employers in each sector reported that AI had created tasks that were not previously done by workers (OECD, 2023c).', 'emploi', 'ocde', 'secondaire', false, '{}'::text[], 'p.12', 'OCDE, 2023 (études de cas dans 8 pays)'),
  ('iag-2026-taches-humaines-13', 'S16', 13, '%', 'Les tâches qui reposent sur l’empathie, la créativité, le leadership et la curiosité n’ont qu’un potentiel de transformation par l’IA de 13 %, car elles dépendent du jugement humain, du contexte et de l’expérience vécue.', 'Tasks tied to empathy, creativity, leadership and curiosity have just a 13% potential for AI transformation since they depend on human … judgement, context and lived experience (WEF, 2025b).', 'competences', 'monde', 'secondaire', false, '{}'::text[], 'p.23', 'World Economic Forum, 2025'),
  ('iag-2026-offres-ia-hors-it-51', 'S16', 51, '%', 'En 2024, 51 % des offres d’emploi liées à l’IA concernaient des postes hors informatique (39 % en 2019), et les ressources humaines figurent parmi les cinq domaines où la demande de compétences IA a crû le plus vite.', 'as large as 51% of AI-related job postings were found outside IT and Computer Science in 2024, compared to 39% in 2019. The Lightcast report points to five sectors where demand for AI skills grew fastest from 2023 to 2024: HR, Marketing & PR, Finance, Education & Training, and Science & Research.', 'competences', 'monde', 'secondaire', false, '{}'::text[], 'p.31', 'Lightcast, 2025'),
  ('iag-2026-competences-ia-base-29-22', 'S16', 29, '%', 'En Europe, les compétences IA de base sont demandées dans 29 % des offres d’emploi qui citent l’IA, mais n’apparaissent que dans 22 % des CV : le déficit touche aussi le premier niveau, pas seulement les experts.', 'Basic AI skills are sought in 29% of vacancies but appear only in 22% of CVs on average. Similarly, advanced AI skills are required in 24% of vacancies but appear only in 15% of CVs.', 'competences', 'europe', 'secondaire', false, '{}'::text[], 'p.33', 'Pal et al., 2025'),
  ('iag-2026-litteratie-ia-faible-40-60', 'S16', 40, '%', 'En Europe, entre 40 % et 60 % des salariés adultes n’ont qu’une compréhension limitée des différentes dimensions de la littératie IA (reconnaître une IA et ses limites, interpréter ses résultats, en mesurer les enjeux éthiques).', 'The findings of the survey show the low AI literacy in the European adult workforce, with between 40-60% of adult workers surveyed possessing a relatively limited understanding of the diverse pillars of AI literacy (Cedefop, 2025).', 'competences', 'europe', 'secondaire', false, '{}'::text[], 'p.42', 'Cedefop, 2025'),
  ('iag-2026-formation-ia-salaries-15', 'S16', 15, '%', 'En Europe, seuls 15 % environ des salariés ont suivi en 2023-2024 une formation visant à améliorer leur usage de l’IA.', 'between 2023-24 only about 15% of employees participated in education or training activities aimed at further improving their knowledge and skills in using AI technology (ibid., 2025).', 'formation', 'europe', 'secondaire', false, '{}'::text[], 'p.42-43', 'Cedefop, 2025'),
  ('iag-2026-main-oeuvre-ia-0-3-5', 'S16', 5, '%', 'Les métiers qui conçoivent ou utilisent professionnellement l’IA à un niveau technique ne représentent qu’entre 0,3 % et 5 % de l’emploi total selon les études, une part faible mais en croissance rapide.', 'the share of the AI workforce ranges from as little as 0.3% to as much as 5% of total employment, with variations across countries and over time. Nevertheless, the demand for AI-related skills has increased rapidly over the past decade', 'emploi', 'monde', 'primaire', false, '{}'::text[], 'p.6', null),
  ('ocde-2026-agentique-autonomie-bornee-25', 'S17', 25, '', 'Parmi 25 organisations pionnières de l’IA agentique interrogées dans 11 pays, aucune ne déploie d’agents à autonomie illimitée : l’exécution autonome reste cantonnée à des tâches définies, avec validation humaine des actions à fort enjeu ou irréversibles.', 'No participating organisation reported deploying agentic AI systems with unrestricted autonomy. Instead, autonomous execution is typically constrained to clearly defined task scopes, with human approval for high-stake or irreversible actions', 'gouvernance', 'monde', 'primaire', false, '{}'::text[], 'p.15', null),
  ('ocde-2026-agentique-taches-structurees-25', 'S17', 25, '', 'Pour les 25 organisations pionnières interrogées, les usages agentiques de court terme se concentrent sur des tâches structurées, dont le résultat peut être vérifié et dont le coût d’une erreur reste limité ou réversible.', 'In the near term, however, they expected adoption to be clustered under narrower conditions: where tasks are structured enough for an agent to plan and execute them; where outcomes can be checked against reliable data or system records; and where the costs of an error is bounded or reversible', 'adoption', 'monde', 'primaire', false, '{}'::text[], 'p.14', null),
  ('ocde-2026-agentique-erosion-expertise-25', 'S17', 25, '', 'Parmi les 25 organisations pionnières de l’IA agentique interrogées, beaucoup craignent que la délégation aux agents érode l’expertise et réduise l’apprentissage par l’expérience des futurs salariés.', 'Many interviewees warned that over time this could erode expertise and reduce opportunities for experiential learning and skills development for future generations of workers.', 'competences', 'monde', 'primaire', false, '{}'::text[], 'p.19', null),
  ('ocde-2026-agentique-penuries-main-oeuvre-25', 'S17', 25, '', 'Parmi les 25 organisations pionnières interrogées, plusieurs présentent l’IA agentique d’abord comme une réponse aux pénuries structurelles de main-d’œuvre, pour augmenter les équipes plutôt que les remplacer.', 'Several organisations … framed agentic AI primarily as a response to structural labour shortages rather than as a substitute for human workers.', 'emploi', 'monde', 'primaire', false, '{}'::text[], 'p.13', null)
